sys_script_include.script:
var ToolGuardRiskEngine = Class.create();
ToolGuardRiskEngine.prototype = {
    initialize: function() {},

    calculateRisk: function(toolGr) {
        // Fetch current cycles and limit safely
        var cyclesVal = toolGr.getValue('u_current_cycles') || toolGr.getValue('current_cycles') || '0';
        var limitVal = toolGr.getValue('u_lifecycle_limit') || toolGr.getValue('lifecycle_limit') || '10000';

        var cycles = parseInt(cyclesVal, 10);
        var limit = parseInt(limitVal, 10);

        // Vector 1: Usage Burden Score (Max 60 points)
        var usageRatio = limit > 0 ? (cycles / limit) : 0;
        var usageRisk = Math.min(Math.round(usageRatio * 60), 60);

        // Vector 2: Recent Inspection Wear Penalty (Max 30 points)
        var inspectionPenalty = 0;
        var inspGr = new GlideRecord('x_snc_toolguard_ai_inspection');
        inspGr.addQuery('u_tool', toolGr.getUniqueValue());
        inspGr.orderByDesc('sys_created_on');
        inspGr.setLimit(1);
        inspGr.query();

        if (inspGr.next()) {
            var condition = inspGr.getValue('u_wear_condition') || inspGr.getValue('wear_condition');
            if (condition === 'Moderate Wear') {
                inspectionPenalty = 10;
            } else if (condition === 'Severe Wear') {
                inspectionPenalty = 20;
            } else if (condition === 'Critical Damage') {
                inspectionPenalty = 30;
            }
        }

        // Vector 3: Overuse Buffer Penalty (Max 10 points)
        var overusePenalty = (usageRatio > 0.90) ? 10 : 0;

        // Total Risk Score Calculation
        var totalRisk = Math.min(usageRisk + inspectionPenalty + overusePenalty, 100);

        // Plain-Language Explainable AI Output
        var reasoning = "Risk Score " + totalRisk + "/100 calculated via Multi-Factor Risk Matrix. " +
            "Breakdown: Usage Burden = " + usageRisk + "/60 (" + Math.round(usageRatio * 100) + "% limit used), " +
            "Inspection Degradation Penalty = " + inspectionPenalty + "/30, " +
            "Overuse Buffer Penalty = " + overusePenalty + "/10.";

        return {
            score: totalRisk,
            reason: reasoning
        };
    },

    type: 'ToolGuardRiskEngine'
};
